(* [comment removed for export] *)
Section TailRefill.
  Variables (sp ra0 s0v s1v s2v s3v s4v s5v gp tp s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (t0 t1 t2 xa1 xa2 xa3 xa4 xa5 xa6 xa7 t3 t4 t5 t6 xra : word) (m : mem).
  Variables (lo : Z) (T : list Z) (rest : list word) (jk jke : list byte).
  Variables (U size TH qcache sb : Z) (k hdq LA qbytes : Z) (cnt : Z) (chunks : list Z) (B : Z) (j0 j1 j2 j3 : word).
  Let Wn := enq_new_W lo (bv_unsigned sp) TH B LA.

  Hypothesis LO : aceil <= lo.  Hypothesis HI : lo + 2944 <= bv_unsigned sp.
  Hypothesis SPT : hidden (bv_unsigned sp + 16 <= 2^47).
  Hypothesis UR : hidden (aapp U 8 /\ AIMG_TOP + 16 <= U /\ U + 8 <= aceil).   (* [comment removed for export] *)
  Hypothesis SZ : 1 <= size < 2^32.
  Hypothesis THR : hidden (akobj TH 4096 /\ TH + 4096 <= aceil /\ TH mod 16 = 0).
  Hypothesis SBR : hidden (AHI_LO <= sb /\ sb + kSpaceSize + kPageSize <= aceil /\ sb mod 65536 = 0).
  Hypothesis CNT : cnt = zlen chunks. Hypothesis HIT : 1 <= cnt <= 2.
  Hypothesis CPS : Forall (fun cp => 0 <= cp < 2^32) chunks.
  Hypothesis HB : B = sb + kBatchClass * 2^32 + hd 0 chunks * 16.
  Hypothesis BR : hidden (AHI_LO <= B /\ B + kBatchSize <= aceil /\ (TH + 4096 <= B \/ B + kBatchSize <= TH)).
  Hypothesis BU : B + kBatchSize <= U - 16 \/ U + 8 <= B.
  Hypothesis KR : 0 <= k /\ k + 1 < 2^64. Hypothesis QB : 0 <= qbytes /\ qbytes + size + kBatchSize <= qcache.
  Hypothesis HDQ : 0 <= hdq < 2^64. Hypothesis QCR : 0 <= qcache < 2^64.
  Hypothesis LAh : k <> 0 -> rw_cells bsegs m LA [C8 (wz 0)]
                   /\ AHI_LO <= LA /\ LA + kBatchSize <= aceil /\ (TH + 4096 <= LA \/ LA + kBatchSize <= TH) /\ (B + kBatchSize <= LA \/ LA + kBatchSize <= B)
                   /\ (LA + kBatchSize <= U - 16 \/ U + 8 <= LA).
  Hypothesis LA0 : k = 0 -> LA = 0.
  Hypothesis LR  : length rest = (255 - length T)%nat.
  Hypothesis NR  : (1 <= length T <= 30)%nat.
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis ST : stk bsegs m lo (bv_unsigned sp + -2272).
  Hypothesis FR : rw_cells bsegs m (bv_unsigned sp + -2272)
      [CB 8 jke; C8 (wz (U + -16)); C8 (wz (TH + OT_CACHE)); C8 (Z_to_bv 64 (bv_unsigned sp + -2128)); C8 (wz size);
       C8 (wz (TH + OT_TQ)); C8 (wz (AINST + OI_Q)); C8 (wz 0x54624)].
  Hypothesis TQ : rw_cells bsegs m (TH + OT_TQ) [C8 (wz k); C8 (wz hdq); C8 (wz LA); C8 (wz qbytes)].
  Hypothesis PC1 : rw_cells bsegs m (TH + 2128) [C4 (wz cnt)].
  Hypothesis PC2 : rw_cells bsegs m (TH + 2136) [C8 (wz kBatchSize)].
  Hypothesis PC3 : u32arr bsegs m (TH + 2144) (wlist (rev chunks)).
  Hypothesis PC4 : stk bsegs m (TH + 2144 + 4 * cnt) (TH + 2208).
  Hypothesis STATS : rw_cells bsegs m (TH + 2768) [C8 j0; C8 j1; C8 j2; C8 j3].
  Hypothesis INST : rw_cells bsegs m (AINST + OI_SPACEBEG) [C8 (wz sb)].
  Hypothesis BJ : stk bsegs m B (B + kBatchSize).
  Hypothesis PFR : rw_cells bsegs m (bv_unsigned sp + -2208) (put_frame sp s6 U TH).
  Hypothesis ESO : rw_cells bsegs m (bv_unsigned sp + -2128) [C8 (wz (bv_unsigned sp + -2128 + 16)); C8 (wz (Z.of_nat (length T)))].
  Hypothesis TRB : u64arr bsegs m (bv_unsigned sp + -2128 + 16) (map wz T ++ rest).
  Hypothesis TFB : rw_cells bsegs m (bv_unsigned sp + -72) [C8 sp].
  Hypothesis F4  : rw_cells bsegs m (bv_unsigned sp + -64) [CB 8 jk; C8 s5v; C8 s4v; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 ra0].

  Definition free_tail_refill_post : machine_state -> Prop := fun ms' =>
    exists (j2' : word) m', free_ret_post sp ra0 s0v s1v s2v s3v s4v s5v gp tp s6 s7 s8 s9 s10 s11 F fc lo m' ms'
    /\ munch Wn m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ rw_cells bsegs m' (TH + OT_TQ) [C8 (wz (k + 1)); C8 (wz (if k =? 0 then B else hdq)); C8 (wz B); C8 (wz (qbytes + (size + kBatchSize)))]
    /\ (k <> 0 -> rw_cells bsegs m' LA [C8 (wz B)])
    /\ rw_cells bsegs m' B [C8 (wz 0); C8 (wz (size + kBatchSize)); C8 (wz 1); C8 (wz (U + -16))]
    /\ stk bsegs m' (B + 32) (B + kBatchSize)
    /\ rw_cells bsegs m' (TH + 2128) [C4 (wz (cnt - 1))]
    /\ u32arr bsegs m' (TH + 2144) (wlist (rev (tl chunks)))
    /\ stk bsegs m' (TH + 2144 + 4 * (cnt - 1)) (TH + 2208)
    /\ rw_cells bsegs m' (TH + 2768) [C8 j0; C8 j1; C8 j2'; C8 j3].
Scheme kc__4 := Elimination for Corelib.Init.Specif.sumbool Sort Prop.
Scheme kc__5 := Elimination for Corelib.Init.Logic.or Sort Prop.

  Theorem free_tail_refill :
    evt bsegs free_tail_refill_post
      (MS (mkR xra (Z_to_bv 64 (bv_unsigned sp + -2272)) gp tp t0 t1 t2 (wz (TH + 2128)) (wz (TH + OT_CACHE))
               (wz 1) xa1 xa2 xa3 xa4 xa5 xa6 xa7
               (wz (U + -16)) (wz (TH + OT_TQ)) (Z_to_bv 64 (bv_unsigned sp + -2128)) (wz size) (wz qcache) s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 0x54784) fc None m (seg_rom bsegs)).
